Object.assign(LOCAL_SCRYFALL_DECK_DB, globalThis.FocusedMagicMandatoryLocalDB||{});
const LOCAL_SCRYFALL_DECK_DB_COUNT=Object.keys(LOCAL_SCRYFALL_DECK_DB).length;
const CONSTRUCTED_EXACT_CACHE_KEY='focused_magic_constructed_exact_cache_v1';
let constructedExactCache={};try{constructedExactCache=JSON.parse(localStorage.getItem(CONSTRUCTED_EXACT_CACHE_KEY)||'{}')||{};}catch(_e){constructedExactCache={};}
const normalizedCardName=x=>String(x||'').trim().toLowerCase();
const exactNameMatches=(requested,raw)=>{const q=normalizedCardName(requested),n=normalizedCardName(raw?.name);if(n===q||n.startsWith(q+' // '))return true;return (raw?.card_faces||[]).some(f=>normalizedCardName(f?.name)===q);};
const SCRYFALL_MIN_INTERVAL_MS=175;
let constructedLastScryfallRequestAt=0;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function paceScryfall(){
  const now=Date.now(),wait=Math.max(0,SCRYFALL_MIN_INTERVAL_MS-(now-constructedLastScryfallRequestAt));
  if(wait)await sleep(wait);
  constructedLastScryfallRequestAt=Date.now();
}
async function constructedFetch(url,attempts=5){
  let last=null;
  for(let i=0;i<attempts;i++){
    await paceScryfall();
    try{
      const r=await fetch(url,{headers:{Accept:'application/json;q=0.9,*/*;q=0.8'},cache:'no-store'});
      if(r.status===429){
        const retryHeader=Number(r.headers.get('Retry-After')||0);
        const waitMs=Math.max(2500,retryHeader>0?retryHeader*1000:0,1200*Math.pow(2,i));
        constructedStatus(`Scryfall rate limit reached. Waiting ${Math.ceil(waitMs/1000)}s, then retrying…`);
        await sleep(waitMs);
        last=new Error('Scryfall HTTP 429 rate limit');
        continue;
      }
      if(r.status>=500&&i+1<attempts){
        const waitMs=1000*Math.pow(2,i);
        constructedStatus(`Scryfall server error ${r.status}. Retrying in ${Math.ceil(waitMs/1000)}s…`);
        await sleep(waitMs);
        last=new Error(`Scryfall HTTP ${r.status}`);
        continue;
      }
      return r;
    }catch(e){
      last=e;
      if(i+1<attempts){
        const waitMs=1000*Math.pow(2,i);
        constructedStatus(`Network fetch failed. Retrying in ${Math.ceil(waitMs/1000)}s…`);
        await sleep(waitMs);
      }
    }
  }
  throw last||new Error('network fetch failed after retries');
}
async function fetchExactConstructedCard(name){
  const key=normalizedCardName(name);
  const local=LOCAL_SCRYFALL_DECK_DB[key];
  if(local){
    if(!exactNameMatches(name,local))throw new Error(`Saved-database identity guard failed for “${name}”.`);
    return E.clone(local);
  }
  const allowLive=!!q('constructedLiveFallback')?.checked;
  if(!allowLive)throw new Error(`“${name}” is not in this build's embedded saved-database subset. No public lookup was used. Enable the explicit live fallback only if this is a user-edited card absent from the saved snapshot subset.`);
  const cached=constructedExactCache[key];
  try{
    const r=await constructedFetch('https://api.scryfall.com/cards/named?exact='+encodeURIComponent(name));
    if(!r.ok){
      let suggestion='';
      if(r.status===404){try{const f=await constructedFetch('https://api.scryfall.com/cards/named?fuzzy='+encodeURIComponent(name),1);if(f.ok){const j=await f.json();suggestion=j.name&&normalizedCardName(j.name)!==key?` Did you mean “${j.name}”?`:'';}}catch(_e){}}
      throw new Error(`Scryfall HTTP ${r.status} for exact card “${name}”.${suggestion}`);
    }
    const raw=await r.json();
    if(!exactNameMatches(name,raw))throw new Error(`Identity guard blocked “${name}” because Scryfall returned “${raw?.name||'unknown'}”.`);
    const compact=E.compact(raw);
    constructedExactCache[key]=compact;
    try{localStorage.setItem(CONSTRUCTED_EXACT_CACHE_KEY,JSON.stringify(constructedExactCache));}catch(_e){}
    return E.clone(compact);
  }catch(e){
    if(cached&&exactNameMatches(name,cached))return E.clone(cached);
    throw new Error(`Failed optional live fallback for “${name}”: ${e?.message||e}. No substitute card was used.`);
  }
}
async function resolveConstructedNames(parsedPair){
  const names=[...new Set([...parsedPair.u.main,...parsedPair.u.sideboard,...parsedPair.a.main,...parsedPair.a.sideboard])];const defs=new Map();let done=0;
  for(const name of names){const source=LOCAL_SCRYFALL_DECK_DB[normalizedCardName(name)]?'saved DB':'explicit live fallback';constructedStatus(`Resolving ${done+1}/${names.length}: ${name} • ${source}`);const d=await fetchExactConstructedCard(name);if(!d||!d.name)throw new Error(`Resolver returned no card definition for “${name}”.`);defs.set(name,d);done++;}
  const expand=arr=>arr.map(n=>E.clone(defs.get(n))),manual=arr=>arr.filter(d=>E.needsManual(d)).length;
  const uMain=expand(parsedPair.u.main),uSide=expand(parsedPair.u.sideboard),aMain=expand(parsedPair.a.main),aSide=expand(parsedPair.a.sideboard);
  return {uMain,uSide,aMain,aSide,uManual:manual(uMain),aManual:manual(aMain),unique:names.length};
}
