async function startConstructedLocal(parsed,providerReason=''){
  q('constructedStart').disabled=true;q('constructedValidate').disabled=true;
  if(providerReason && q('constructedLiveFallback'))q('constructedLiveFallback').checked=true;
  try{const r=await resolveConstructedNames(parsed);const uExtra=`Exact Scryfall resolution passed. ${r.uManual}/${r.uMain.length} main-deck cards carry manual/partial automation text.`;const aExtra=`Exact Scryfall resolution passed. ${r.aManual}/${r.aMain.length} main-deck cards carry manual/partial automation text.`;writeConstructedSummary('constructedUserSummary',parsed.u,uExtra,false);writeConstructedSummary('constructedAiSummary',parsed.a,aExtra,false);
    const selected=q('constructedProfile')?.value;
    matchContext={mode:'constructed',userName:selected==='mandatory'?'You — v0.6.5 mandatory deck':'You — Page, Loose Leaf',aiName:'AI — Dimir',userSideboard:r.uSide,aiSideboard:r.aSide};
    spar=E.newSparring(freshMatchSeed(q('constructedSeed').value,'constructed'),q('constructedDifficulty').value,r.uMain,r.aMain);spar.version='CONSTRUCTED_SPARRING_0.1';spar.log[0]=`${providerReason?`Argentum fallback (${providerReason}). `:''}Constructed AI sparring begins. User deck ${r.uMain.length} cards; AI deck ${r.aMain.length} cards. Sideboards retained: ${r.uSide.length}/${r.aSide.length}. User plays first and skips the first-turn draw.`;
    q('constructedModal').classList.remove('open');q('sealedModal').classList.add('open');setMatchContextLabels();enterTabletop();renderMatch();pumpMatchAI();constructedStatus(`Local fallback match started. Resolved ${r.unique} exact card names.`);matchStatus(providerReason?'Argentum rejected/failed; switched visibly to local/manual fallback. Report the first broken card interaction and keep playing.':'Constructed match started in local fallback. Complex card text remains visibly manual/partial.');
  }catch(e){spar=null;constructedStatus(e.message,true);matchStatus('Constructed match not started; both provider and local fallback failed closed.');}finally{q('constructedStart').disabled=false;q('constructedValidate').disabled=false;}
}
async function startConstructedMatch(){
  const parsed=validateConstructedUI();if(!parsed)return;
  if(!window.FocusedMagicArgentum?.providerEnabled?.()){
    constructedStatus('Patched Argentum provider is not configured. Constructed play is blocked rather than silently switching to the incomplete Sealed/Local fallback. Open Argentum Engine → Diagnostics after deploying the patched provider.',true);
    window.FocusedMagicArgentum?.open?.();
    return;
  }
  try{
    constructedStatus('Checking the configured Argentum registry before starting the match…');
    const coverage=await window.FocusedMagicArgentum.catalogCoverage([...parsed.u.main,...parsed.u.sideboard,...parsed.a.main,...parsed.a.sideboard]);
    if(coverage.missing?.length){
      const publicHint=coverage.publicUpstream?' The configured endpoint is the public upstream registry; Focused Magic requires the patched provider.':'';
      throw new Error(`Registry gate failed. Missing after canonical aliasing: ${coverage.missing.join(', ')}.${publicHint}`);
    }
    window.FocusedMagicArgentum.startText(q('constructedUserDeck').value,q('constructedAiDeck').value,{label:'Constructed',aiLabel:'Dimir Tempo',presentation:'tabletop',onProviderFail:(msg)=>{
      window.FocusedMagicArgentum?.closeTabletop?.();
      q('constructedModal').classList.add('open');
      constructedStatus(`Argentum runtime failed: ${msg}. Match stopped. No automatic Sealed/Local fallback was started, so this provider failure cannot masquerade as broken card abilities.`,true);
    }});
    q('constructedModal').classList.remove('open');
    constructedStatus(`Argentum registry gate passed and exact-list launch was requested: you ${parsed.u.main.length}+${parsed.u.sideboard.length}; opponent ${parsed.a.main.length}+${parsed.a.sideboard.length}.`);
  }catch(e){
    window.FocusedMagicArgentum?.closeTabletop?.();
    q('constructedModal').classList.add('open');
    constructedStatus(`Constructed blocked at Argentum registry/provider gate: ${e.message}`,true);
  }
}

async function fetchAllScryfall(query){let url='https://api.scryfall.com/cards/search?order=set&unique=prints&q='+encodeURIComponent(query),out=[],guard=0;while(url&&guard++<10){const r=await fetch(url,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error(`Scryfall ${r.status} for ${query}`);const j=await r.json();out.push(...(j.data||[]));url=j.has_more?j.next_page:null;if(url)await new Promise(res=>setTimeout(res,90));}return out;}
async function loadData(){if(db)return db;status('Loading current Reality Fracture card data…');q('sealedSourceStatus').textContent='Contacting Scryfall…';const raw=await fetchAllScryfall('set:fra');let spg=[],promos=[];try{spg=(await fetchAllScryfall('set:spg year:2026')).filter(c=>c.released_at==='2026-10-02');}catch(e){}try{promos=await fetchAllScryfall('set:fra is:prerelease');}catch(e){}db=E.buildDatabase(raw,spg,promos);const msg=`Loaded ${db.base.length} canonical FRA cards • ${db.echoPairs.length}/43 echoed pairs • ${db.specials.length} matching Special Guests • ${db.promos.length} prerelease promo printings.`;q('sealedSourceStatus').textContent=msg+(db.warnings.length?' Warnings: '+db.warnings.join(' '):'');if(db.warnings.length)q('sealedSourceStatus').classList.add('sealed-warning');status('Reality Fracture data ready.');return db;}
